css:
.vossberg-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b3440;
    background: #eef1f5;
    border-radius: 14px;
}

.vossberg-container * {
    box-sizing: border-box;
}

.vossberg-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(120deg, #1b2a3a 0%, #243b55 60%, #2f5070 100%);
    color: #f3f6fa;
    border-radius: 12px;
    margin-bottom: 20px;
    border-bottom: 5px solid #e8a13a;
    box-shadow: 0 10px 28px rgba(27, 42, 58, 0.28);
}

.vossberg-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.vossberg-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f2c178;
    background: rgba(232, 161, 58, 0.14);
    border: 1px solid rgba(232, 161, 58, 0.40);
    padding: 5px 14px;
    border-radius: 4px;
}

.vossberg-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c7d4e2;
}

.vossberg-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #5a6878;
    margin-bottom: 18px;
    padding: 4px 2px;
}

.vossberg-period-counter #currentDay,
.vossberg-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f5070;
}

.vossberg-round-name {
    background: #243b55;
    color: #f2c178;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-left: 4px;
}

.vossberg-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #a8631a;
    background: #fbeed6;
    border: 1px solid #efcf95;
    padding: 4px 12px;
    border-radius: 4px;
}

.vossberg-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.vossberg-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.08);
    border-top: 4px solid #2f5070;
}

.vossberg-card-profit { border-top-color: #2f7d5a; }
.vossberg-card-pipeline { border-top-color: #3a6ea5; }
.vossberg-card-fit { border-top-color: #7a5cb0; }
.vossberg-card-speed { border-top-color: #e8a13a; }

.vossberg-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a8898;
}

.vossberg-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2a3a;
    font-variant-numeric: tabular-nums;
}

.vossberg-card-profit .vossberg-value { color: #2f7d5a; }
.vossberg-card-pipeline .vossberg-value { color: #3a6ea5; }
.vossberg-card-fit .vossberg-value { color: #7a5cb0; }
.vossberg-card-speed .vossberg-value { color: #c87f1d; }

.vossberg-sublabel {
    font-size: 0.75rem;
    color: #8693a3;
    line-height: 1.35;
}

.vossberg-profit-negative .vossberg-value { color: #c0392b; }
.vossberg-profit-positive .vossberg-value { color: #2f7d5a; }

.vossberg-speed-high { border-top-color: #2f7d5a; }
.vossberg-speed-high .vossberg-value { color: #2f7d5a; }
.vossberg-speed-low { border-top-color: #c0392b; }
.vossberg-speed-low .vossberg-value { color: #c0392b; }

.vossberg-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b2a3a;
    border: 1px solid #243b55;
    color: #d4dde7;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.vossberg-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f2c178;
}

.vossberg-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e8a13a;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.07);
}

.vossberg-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.vossberg-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a3a;
    margin-bottom: 6px;
}

.vossberg-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #41505f;
}

.vossberg-briefing-text strong { color: #2f5070; }
.vossberg-briefing-text em { color: #a8631a; font-style: italic; }

.vossberg-controls {
    background: #ffffff;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.07);
}

.vossberg-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a3a;
    border-bottom: 2px solid #e2e8ef;
    padding-bottom: 8px;
}

.vossberg-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3440;
    margin: 14px 0 6px;
}

.vossberg-container select,
.vossberg-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2ccd8;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #f7f9fb;
    color: #1b2a3a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.vossberg-container select:focus,
.vossberg-container input[type="number"]:focus {
    outline: none;
    border-color: #2f5070;
    box-shadow: 0 0 0 3px rgba(47, 80, 112, 0.16);
}

.vossberg-container select option {
    background-color: #ffffff;
    color: #1b2a3a;
}

.vossberg-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f5070;
}

.vossberg-range-readout,
.vossberg-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a6878;
    margin-top: 4px;
}

.vossberg-range-readout span:last-child,
.vossberg-alloc-readout span:nth-child(2) {
    color: #2f5070;
    font-weight: 800;
}

.vossberg-hint {
    font-size: 0.8rem;
    color: #8693a3;
    margin-top: 4px;
    line-height: 1.4;
    background: #f3f6fa;
    border-left: 3px solid #cdd7e2;
    padding: 7px 10px;
    border-radius: 4px;
}

.vossberg-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.vossberg-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f6fa;
    border: 1px solid #d6dde6;
    border-radius: 6px;
    padding: 8px 12px;
}

.vossberg-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #41505f;
}

.vossberg-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.vossberg-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.vossberg-container .btn-primary {
    background: linear-gradient(135deg, #243b55 0%, #2f5070 100%);
    border: none;
    color: #ffffff;
    padding: 11px 28px;
    border-radius: 6px;
    box-shadow: 0 6px 16px rgba(36, 59, 85, 0.32);
}

.vossberg-container .btn-primary:hover {
    filter: brightness(1.10);
}

.vossberg-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c2ccd8;
    color: #5a6878;
    background: transparent;
}

.vossberg-coach {
    background: linear-gradient(120deg, #1b2a3a 0%, #243b55 100%);
    color: #d4dde7;
    border: 1px solid #243b55;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 42, 58, 0.20);
}

.vossberg-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f2c178;
    margin-bottom: 8px;
}

.vossberg-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.vossberg-coach-body strong { color: #f2c178; }
.vossberg-coach-body em { color: #8fb4d8; font-style: italic; }

.vossberg-history,
.vossberg-chart {
    background: #ffffff;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.07);
}

.vossberg-history h3,
.vossberg-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a3a;
}

.vossberg-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #41505f;
}

.vossberg-container table#usfHistoryTable th {
    background: #1b2a3a;
    color: #f2c178;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #243b55;
}

.vossberg-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e2e8ef;
    color: #41505f;
}

.vossberg-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f5f8fb;
}

.vossberg-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .vossberg-container {
        padding: 14px;
    }
    .vossberg-header h1 {
        font-size: 1.7rem;
    }
    .vossberg-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .vossberg-value {
        font-size: 2rem;
    }
    .vossberg-clock {
        margin-left: 0;
    }
    .vossberg-period-counter {
        font-size: 0.88rem;
    }
    .vossberg-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .vossberg-alloc-row {
        flex-wrap: wrap;
    }
    .vossberg-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .vossberg-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, navy/gold) */
.vossberg-cm { background:#f4f6f9; color:#1b2a3a; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(27,42,58,0.2); }
.vossberg-cm-head { text-align:center; border-bottom:1px solid #d3dae3; padding-bottom:14px; margin-bottom:16px; }
.vossberg-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#2f5070; font-weight:700; }
.vossberg-cm-scorewrap { margin:8px 0 2px; }
.vossberg-cm-score { font-size:52px; font-weight:800; color:#243b55; line-height:1; }
.vossberg-cm-score-max { font-size:20px; color:#8492a2; font-weight:600; }
.vossberg-cm-grade { font-size:19px; font-weight:700; color:#1b2a3a; margin-top:4px; }
.vossberg-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.vossberg-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.vossberg-cm-met { background:#cfe6dd; color:#12705a; }
.vossberg-cm-fail { background:#f3ddd4; color:#a4482c; }
.vossberg-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.vossberg-cm-metric { background:#e6ecf3; border-radius:10px; padding:12px 16px; min-width:96px; text-align:center; }
.vossberg-cm-metric-val { font-size:20px; font-weight:800; color:#1b2a3a; }
.vossberg-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#2f5070; margin-top:3px; }
.vossberg-cm-insights { background:#e6ecf3; border-radius:10px; padding:14px 18px; }
.vossberg-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#2f5070; font-weight:700; margin-bottom:8px; }
.vossberg-cm-insights ul { margin:0; padding-left:18px; }
.vossberg-cm-insights li { font-size:14px; line-height:1.5; color:#26374a; margin-bottom:7px; }

