            else if (trapped) insights.push(window.mySimulation.t(`insight_trapped`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!solvent) insights.push(window.mySimulation.t(`insight_profit_low`));
            else if (profit >= this.EBIT_BASE + 6) insights.push(window.mySimulation.t(`insight_profit_strong`));
            if (ds.strangledVenture) insights.push(window.mySimulation.t(`insight_strangled`));
            if (ds.overSeparated) insights.push(window.mySimulation.t(`insight_overseparated`));
            if (ds.starvedCore) insights.push(window.mySimulation.t(`insight_starved`));
            if (pipeline >= 60 && fit >= 60 && speed >= 55) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                profit: profit,
                pipeline: pipeline,
                fit: fit,
                speed: speed,
                solvent: solvent,
                futureReady: futureReady,
                ambidextrous: ambidextrous,
                trapped: trapped,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="vossberg-cm-badge ` + (s.met ? `vossberg-cm-met` : `vossberg-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.solvent === false) badges.push(`<span class="vossberg-cm-badge vossberg-cm-fail">` + t(`cm_fail_solvent`) + `</span>`);
            if (s.futureReady === false) badges.push(`<span class="vossberg-cm-badge vossberg-cm-fail">` + t(`cm_fail_future`) + `</span>`);
            if (s.ambidextrous === false) badges.push(`<span class="vossberg-cm-badge vossberg-cm-fail">` + t(`cm_fail_ambi`) + `</span>`);
            const kpi = (label, val) => `<div class="vossberg-cm-metric"><div class="vossberg-cm-metric-val">` + val + `</div><div class="vossberg-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_profit`), (s.profit != null ? this._fmtMoney(Number(s.profit)) : `-`))
                + kpi(t(`cm_pipeline`), (s.pipeline != null ? Math.round(s.pipeline) : 0))
                + kpi(t(`cm_fit`), (s.fit != null ? Math.round(s.fit) : 0))
                + kpi(t(`cm_speed`), (s.speed != null ? Math.round(s.speed) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="vossberg-cm">`
                + `<div class="vossberg-cm-head"><div class="vossberg-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="vossberg-cm-scorewrap"><span class="vossberg-cm-score">` + score + `</span><span class="vossberg-cm-score-max">/100</span></div>`
                + `<div class="vossberg-cm-grade">` + grade + `</div>`
                + `<div class="vossberg-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="vossberg-cm-metrics">` + kpis + `</div>`
                + `<div class="vossberg-cm-insights"><div class="vossberg-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.starvedCore) return window.mySimulation.t(`hint_starved`);
            if (ds.strangledVenture) return window.mySimulation.t(`hint_strangled`);
            if (ds.overSeparated) return window.mySimulation.t(`hint_overseparated`);
            if (ds.profit <= this.EBIT_BASE - 8 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_profit`);
            if (state.currentPeriod >= 2 && ds.pipeline < 30) return window.mySimulation.t(`hint_pipeline`);
            if (state.currentPeriod >= 3 && ds.speed < 35) return window.mySimulation.t(`hint_speed`);
            if (ds.pipeline >= 60 && ds.fit >= 60 && ds.speed >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.profit`, label: `EBIT`, i18nKey: `col_profit`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.pipeline`, label: `Pipeline`, i18nKey: `col_pipeline`, formatter: (v) => Math.round(v) },
                { key: `results.fit`, label: `Fit`, i18nKey: `col_fit`, formatter: (v) => Math.round(v) },
                { key: `results.speed`, label: `Speed`, i18nKey: `col_speed`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Adapt or Anchor`,
